CREATE FUNCTION public.current_owner_account() RETURNS bigint
    LANGUAGE sql STABLE
    AS $$ SELECT NULLIF(pg_catalog.current_setting('hephaestus.owner_account', true), '')::bigint $$;

ALTER TABLE public.account_export ENABLE ROW LEVEL SECURITY;
CREATE POLICY account_export_owner ON public.account_export TO hephaestus_app
    USING (account_id = public.current_owner_account())
    WITH CHECK (account_id = public.current_owner_account());

CREATE FUNCTION public.person_row_sweep(rule text, cutoff timestamptz) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
    AS $$
    DECLARE affected integer;
    BEGIN
        IF rule IS DISTINCT FROM 'EXPIRED_EXPORTS' OR cutoff IS NULL THEN
            RAISE EXCEPTION 'Invalid person row sweep' USING ERRCODE = '22023';
        END IF;
        UPDATE public.account_export
        SET status = 'EXPIRED', payload = NULL
        WHERE status = 'READY' AND expires_at < LEAST(cutoff, clock_timestamp());
        GET DIAGNOSTICS affected = ROW_COUNT;
        RETURN affected;
    END
    $$;
ALTER FUNCTION public.person_row_sweep(text, timestamptz) OWNER TO hephaestus_owner;
REVOKE ALL ON FUNCTION public.person_row_sweep(text, timestamptz) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.person_row_sweep(text, timestamptz) TO hephaestus_app;
